<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Investment & Add-ons • {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#061018;--card:#071821;--muted:#9bb0b8;--accent:#c3a57a;--accent-dark:#8f6e4a}
