      <a href="events.html" style="color:#eef6f8;text-decoration:none;margin-right:12px">Gatherings</a>
      <a href="private-sessions.html" style="color:#eef6f8;text-decoration:none;margin-right:12px">Private</a>
      <a class="" href="{{PRIMARY_CTA_URL}}" style="color:var(--card);background:var(--accent);padding:8px 12px;border-radius:8px;text-decoration:none;margin-left:12px">{{PRIMARY_CTA_LABEL}}</a>
