    </section>

  </main>

  <footer>
    <div style="max-width:1100px;margin:20px auto;padding:0 20px;color:var(--muted)">Questions or bulk purchase? Email <a href="mailto:{{EMAIL}}" style="color:var(--accent)">{{EMAIL}}</a> or call <a href="tel:{{PHONE}}" style="color:var(--accent)">{{PHONE}}</a>.</div>
  </footer>

  <script>
    // reveal behavior shared
    (function(){
      const prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      const nodes = document.querySelectorAll('[data-reveal]');
      if(prefersReduced){ nodes.forEach(n=>n.classList.add('revealed')); return }
      const observer = new IntersectionObserver((entries)=>{ entries.forEach(en=>{ if(en.isIntersecting){ en.target.classList.add('revealed'); observer.unobserve(en.target); } }); },{threshold:0.12});
      nodes.forEach(n=>observer.observe(n));
    })();
  </script>
</body>
</html>"} 
